let html;

if (KIND === 'not_produced') {
  const a = first('Analyse Evidence').analysis || {};
  const counts = a.counts || {};
  const flagged = a.decision === 'flag_review';
  subject = 'No course produced yet: ' + clean(req.topic);
  html = emailLayout({
    preheader: 'The research did not support producing this course yet.',
    eyebrow: 'Course request',
    title: 'We held off on this course',
    subtitle: clean(req.topic),
    intro: [
      'Hi,',
      'We looked into your request for a course on "' + clean(req.topic) + '" and decided not to produce it yet. ' +
        (flagged
          ? 'The evidence review raised concerns, and there were not enough relevant studies to go ahead with confidence.'
          : 'The research we found does not support a course at this stage.'),
    ],
    blocks: [
      section('What the review found', p(clean(a.rationale)) + facts([
        ['Sources reviewed', String(counts.total || 0)],
        ['Relevant to fitness and recovery', String(counts.relevant || 0)],
      ])),
      (a.safety_flags || []).length ? section('Worth knowing before revisiting it', list(a.safety_flags.map(clean))) : '',
      (a.overrides || []).length ? callout('Policy check', p(a.overrides.map(clean).join('. ') + '.', { gap: 0, size: 14 }), 'warn') : '',
    ],
    closing: ['If you would still like it produced, submit the request again with "Produce even if evidence is thin" set to Yes, and the course will be written and sent to you for review as usual.'],
  });
} else if (KIND === 'gate_blocked') {
  const c = first('Build Course Content');
  const title = clean((c.package || {}).title || req.topic);
  const issues = ((c.gate || {}).blocking || []).map((f) =>
    '<b>' + esc(place(f.where)) + '.</b> ' + esc(REASON[f.code] || f.code) +
    (f.detail && !/^\d+ /.test(f.detail) ? '<br><span style="color:' + KIT.muted + ';">&ldquo;' + esc(clean(f.detail)) + '&rdquo;</span>' : ' <span style="color:' + KIT.muted + ';">(' + esc(clean(f.detail)) + ')</span>'));
  subject = 'Needs changes before production: ' + title;
  html = emailLayout({
    preheader: issues.length + ' issue(s) stopped this draft before any narration or video was made.',
    eyebrow: 'Content check',
    title: 'This draft needs changes',
    subtitle: title,
    intro: [
      'Hi,',
      'The draft of "' + title + '" was written, but it did not pass our content checks, so production stopped before any narration or video was made. No voice credits were used.',
    ],
    blocks: [
      callout('What needs changing', list(issues, { html: true, size: 14 }), 'bad'),
    ],
    closing: ['This version is saved as needing revision. Submitting the topic again will write a fresh draft with the same checks applied.'],
  });
} else if (KIND === 'published') {
  const c = first('Build Course Content');
  const course = first('Create Course');
  const media = first('Produce Media');
  const decision = first('Normalize Decision');
  const title = clean((c.package || {}).title);
  const LABEL = { pptx: 'Slides (PowerPoint)', mp4: 'Training video', worksheet: 'Worksheet', quiz: 'Knowledge-check quiz', exam: 'Certification exam', answer_key: 'Answer key', sources: 'Reference list' };
  subject = 'Published: ' + title + ' (version ' + course.version + ')';
  html = emailLayout({
    preheader: 'Version ' + course.version + ' is live in the LMS.',
    eyebrow: 'Published',
    title: title,
    subtitle: 'Version ' + course.version + ' is now published',
    intro: [
      'Hi,',
      'Thanks for approving "' + title + '". Version ' + course.version + ' has been published to the LMS. For now that is the test target, until the GymRamp LMS connection is set up.',
    ],
    blocks: [
      decision.comments ? callout('Your review notes', p(clean(decision.comments), { gap: 0, size: 14 }), 'ok') : '',
      section('Course files', facts((media.files || []).map((f) => [LABEL[f.kind] || f.kind, link('Download', f.url)]))),
    ],
    closing: [],
  });
} else if (KIND === 'failure') {
  const failed = first('Mark Failed');
  const url = 'http://localhost:5678/workflow/' + $workflow.id + '/executions/' + $execution.id;
  subject = 'Course production stopped: ' + clean(req.topic);
  html = emailLayout({
    preheader: 'An error stopped production partway through.',
    eyebrow: 'Production error',
    title: 'Production stopped partway through',
    subtitle: clean(req.topic),
    intro: [
      'Hi,',
      'Production of "' + clean(req.topic) + '" hit an error and stopped, so this version has been marked as failed. Nothing was sent for review or published.',
    ],
    blocks: [
      callout('The error', p(clean(failed.failure || 'No error message was recorded.'), { gap: 0, size: 14 }), 'bad'),
      section('Next steps', p('The full run, node by node, is in the ' + link('n8n execution log', url) + '. Once the cause is fixed, submit the topic again to start a new version.', { html: true })),
    ],
    closing: [],
  });
} else {
  throw new Error('compose-email: unknown KIND ' + KIND);
}

return [{ json: { subject, html }, pairedItem: { item: 0 } }];

parameters.query:
WITH v AS (UPDATE course_versions SET status = 'in_review', updated_at = now() WHERE id = $1 RETURNING course_id),
c AS (UPDATE courses SET status = 'in_review', updated_at = now() WHERE id = (SELECT course_id FROM v) RETURNING id)
SELECT (SELECT count(*) FROM c) AS updated;

parameters.jsCode:
// ---- GymRamp email kit ------------------------------------------------------
// Prepended by build-workflows.js to every Code node that writes an email, so all
// messages share one look. Same rules as the earlier newsletter projects, because
// email clients are hostile: inline styles only (Gmail strips <style>), nested
// tables (no flexbox/grid), a centred 640px container on a soft background,
// web-safe fonts, no external images. Everything interpolated is HTML-escaped.

const KIT = {
  font: "system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif",
  navy: '#0B1F33', accent: '#FF6B2C', page: '#F2F4F7', card: '#FFFFFF',
  text: '#1B2733', muted: '#5B6673', rule: '#E4E8EE',
  ok: '#1E7F4F', warn: '#B26A00', bad: '#B3261E',
};

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function p(text, opts) {
  const o = opts || {};
  return '<p style="margin:0 0 ' + (o.gap == null ? 14 : o.gap) + 'px;font-size:' + (o.size || 15) + 'px;line-height:1.6;color:' +
    (o.color || KIT.text) + ';">' + (o.html ? text : esc(text)) + '</p>';
}

function list(items, opts) {
  const o = opts || {};
  const rows = items.filter(Boolean).map((it) =>
    '<li style="margin:0 0 8px;font-size:' + (o.size || 15) + 'px;line-height:1.55;color:' + KIT.text + ';">' + (o.html ? it : esc(it)) + '</li>').join('');
  return rows ? '<ul style="margin:0 0 14px;padding-left:20px;">' + rows + '</ul>' : '';
}

function section(label, inner) {
  return '<tr><td style="padding:26px 32px 4px;">' +
    '<div style="font-size:12px;letter-spacing:1.4px;font-weight:700;color:' + KIT.navy + ';text-transform:uppercase;">' + esc(label) + '</div>' +
    '<div style="width:40px;height:3px;background:' + KIT.accent + ';margin:8px 0 14px;line-height:3px;font-size:0;">&nbsp;</div>' +
    inner + '</td></tr>';
}

function callout(title, inner, tone) {
  const color = { ok: KIT.ok, warn: KIT.warn, bad: KIT.bad }[tone] || KIT.accent;
  const tint = { ok: '#EEF7F1', warn: '#FFF6E8', bad: '#FCEDEC' }[tone] || '#FFF3EC';
  return '<tr><td style="padding:22px 32px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' +
    '<tr><td style="background:' + tint + ';border-left:4px solid ' + color + ';padding:14px 18px;">' +
    '<div style="font-size:14px;font-weight:700;color:' + color + ';margin-bottom:6px;">' + esc(title) + '</div>' + inner +
    '</td></tr></table></td></tr>';
}

function button(label, href) {
  return '<table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:6px 0 4px;"><tr>' +
    '<td style="background:' + KIT.accent + ';border-radius:6px;">' +
    '<a href="' + esc(href) + '" style="display:inline-block;padding:13px 26px;font-family:' + KIT.font +
    ';font-size:15px;font-weight:700;color:#FFFFFF;text-decoration:none;">' + esc(label) + '</a></td></tr></table>';
}

// rows: [[label, valueHtml]]
function facts(rows) {
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 10px;">' +
    rows.filter(Boolean).map(([k, v]) =>
      '<tr><td style="padding:7px 12px 7px 0;border-bottom:1px solid ' + KIT.rule + ';font-size:13px;color:' + KIT.muted +
      ';width:38%;vertical-align:top;">' + esc(k) + '</td><td style="padding:7px 0;border-bottom:1px solid ' + KIT.rule +
      ';font-size:14px;color:' + KIT.text + ';vertical-align:top;">' + v + '</td></tr>').join('') + '</table>';
}

function link(label, href) {
  return '<a href="' + esc(href) + '" style="color:' + KIT.accent + ';text-decoration:none;font-weight:600;">' + esc(label) + '</a>';
}

// blocks are <tr> strings from section()/callout(); intro is plain text paragraphs.
function emailLayout(o) {
  const intro = (o.intro || []).map((t) => p(t)).join('');
  return '<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>' +
    '<body style="margin:0;padding:0;background:' + KIT.page + ';">' +
    '<div style="display:none;max-height:0;overflow:hidden;opacity:0;">' + esc(o.preheader || '') + '</div>' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:' + KIT.page + ';border-collapse:collapse;"><tr><td align="center" style="padding:28px 12px;">' +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:640px;background:' + KIT.card +
    ';border-collapse:collapse;font-family:' + KIT.font + ';border-radius:8px;overflow:hidden;">' +
    '<tr><td style="background:' + KIT.navy + ';padding:22px 32px;">' +
    '<div style="font-size:12px;letter-spacing:2px;font-weight:700;color:' + KIT.accent + ';">GYMRAMP' + (o.eyebrow ? ' &middot; ' + esc(o.eyebrow).toUpperCase() : '') + '</div>' +
    '<div style="font-size:22px;line-height:1.3;font-weight:700;color:#FFFFFF;margin-top:8px;">' + esc(o.title) + '</div>' +
    (o.subtitle ? '<div style="font-size:14px;color:#C9D3DD;margin-top:6px;">' + esc(o.subtitle) + '</div>' : '') +
    '</td></tr>' +
    '<tr><td style="padding:26px 32px 0;">' + intro + '</td></tr>' +
    (o.blocks || []).join('') +
    '<tr><td style="padding:26px 32px 28px;">' + (o.closing || []).map((t) => p(t)).join('') +
    p('GymRamp Course Factory', { color: KIT.muted, size: 14, gap: 0 }) + '</td></tr>' +
    '<tr><td style="background:' + KIT.page + ';padding:14px 32px;font-size:12px;line-height:1.5;color:' + KIT.muted + ';">' +
    esc(o.footer || 'Automated message from the GymRamp Course Factory. Course content is educational and is never published without human approval.') +
    '</td></tr></table></td></tr></table></body></html>';
}
// ---- end email kit ------------------------------------------------------------

// n8n Code node: "Build Review Message"   (GymRamp · Course Factory)
// MODE: Run Once for All Items
//
// Everything an administrator needs to approve AI-written health education, in one
// email: what the course is, any concerns up front, the files, the statements worth
// a second look, and every claim beside the source it rests on.
//
// The decision button points at the Wait node's form. Its URL only exists at run
// time, so the HTML carries %%REVIEW_URL%% and the send node substitutes
// $execution.resumeFormUrl. The email kit is prepended by the build script.
//
// Output: { subject, html, text (for Slack), channel }

const cfg = $('Config').first().json;
const course = $('Create Course').first().json;
const a = $('Analyse Evidence').first().json.analysis || {};
const content = $('Build Course Content').first().json;
const media = $('Produce Media').first().json;

const gate = content.gate || {};
const stats = gate.stats || {};
const pkg = content.package || {};
const clean = (s) => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
const title = clean(pkg.title);

const LABEL = { pptx: 'Slides (PowerPoint)', mp4: 'Training video', worksheet: 'Worksheet', quiz: 'Knowledge-check quiz', exam: 'Certification exam', answer_key: 'Answer key', sources: 'Reference list' };
const minutes = media.video_seconds ? Math.floor(media.video_seconds / 60) + ' min ' + Math.round(media.video_seconds % 60) + ' s' : '';
const voice = media.tts_provider === 'elevenlabs' ? 'ElevenLabs' : media.tts_provider === 'edge' ? 'Microsoft neural voice' : 'unknown';

const CHECK = {
  UNCITED_CLAIM: 'Sounds like a research finding but has no source attached.',
  DOSE_STATED: 'Mentions a dose. It is cited, but worth confirming against the source.',
  DISEASE_TREATMENT_CLAIM: 'Talks about treating a condition. It is cited, but check the wording stays within scope.',
  ASSESSMENT_SHORT: 'Has fewer questions than planned.',
};
const place = (w) => String(w || '').replace(/^slide (\d+) bullet$/, 'Slide $1, on screen').replace(/^slide (\d+)$/, 'Slide $1')
  .replace(/^intro$/, 'Introduction').replace(/^takeaways$/, 'Key takeaways').replace(/^(quiz|exam)$/, (m) => m[0].toUpperCase() + m.slice(1));

const advisories = (gate.advisory || []).slice(0, 15).map((f) =>
  '<b>' + esc(place(f.where)) + '.</b> ' + esc(CHECK[f.code] || f.code) +
  (/^\d+ of \d+/.test(f.detail) ? ' <span style="color:' + KIT.muted + ';">(' + esc(f.detail) + ')</span>' : '<br><span style="color:' + KIT.muted + ';">&ldquo;' + esc(clean(f.detail)) + '&rdquo;</span>'));

// Claims grouped by where they appear, each with its numbered sources.
const bySlide = new Map();
for (const c of content.claims || []) {
  const key = c.slide_no === 0 ? 'Introduction' : c.slide_no > (pkg.slides || []).length ? 'Key takeaways' : 'Slide ' + c.slide_no + ': ' + clean((pkg.slides[c.slide_no - 1] || {}).title);
  if (!bySlide.has(key)) bySlide.set(key, []);
  const tag = c.status === 'cited' ? '' : ' <span style="color:' + KIT.warn + ';font-weight:600;">(no source)</span>';
  bySlide.get(key).push(esc(clean(c.text)) + tag);
}
const claimsHtml = [...bySlide.entries()].map(([k, items]) =>
  '<div style="font-size:13px;font-weight:700;color:' + KIT.navy + ';margin:10px 0 6px;">' + esc(k) + '</div>' + list(items, { html: true, size: 14 })).join('');

const refsHtml = (content.references || []).map((r) =>
  '<p style="margin:0 0 10px;font-size:13px;line-height:1.5;color:' + KIT.text + ';"><b>[' + r.n + ']</b> ' + esc(r.citation) +
  (r.url ? ' ' + link('Open', r.url) : '') + '</p>').join('');

const flagged = a.decision === 'flag_review';
const html = emailLayout({
  preheader: 'Ready for your review: ' + title + '. Nothing is published until you approve it.',
  eyebrow: 'Ready for review',
  title: title,
  subtitle: clean(pkg.subtitle) + ' · Version ' + course.version,
  intro: [
    'Hi,',
    'A new draft of "' + title + '" is ready for you. It has been researched, written, narrated and packaged, and it is waiting on your decision. Nothing reaches the LMS until you approve it.',
  ],
  blocks: [
    flagged
      ? callout('Please read this first: the evidence review flagged this topic',
          p(clean(a.rationale), { size: 14 }) + ((a.safety_flags || []).length ? list(a.safety_flags.map(clean), { size: 14 }) : ''), 'warn')
      : ((a.safety_flags || []).length ? callout('Points to keep in mind', list(a.safety_flags.map(clean), { size: 14 }), 'warn') : ''),
    '<tr><td style="padding:24px 32px 0;">' + button('Approve or request changes', '%%REVIEW_URL%%') +
      p('Opens a short form (sign in with the GymRamp form login). If you request changes, tell us what should be different.', { size: 13, color: KIT.muted, gap: 0 }) + '</td></tr>',
    section('What is in this version', facts([
      ['Slides', (stats.slides || 0) + ' content slides, plus title, takeaways and references'],
      ['Training video', esc(minutes) + ', narrated with ' + esc(voice) + (media.tts_fallback_reason ? ' <span style="color:' + KIT.warn + ';">(ElevenLabs was unavailable)</span>' : '')],
      ['Assessments', 'Worksheet, ' + (stats.quiz_questions || 0) + '-question quiz, ' + (stats.exam_questions || 0) + '-question certification exam (pass mark ' + (pkg.exam && pkg.exam.pass_mark_percent || 80) + '%)'],
      ['Sources', (stats.references || 0) + ' studies cited; ' + (stats.claims_cited || 0) + ' statements carry a source'],
    ].map(([k, v]) => [k, v]))),
    section('Files', facts((media.files || []).map((f) => [LABEL[f.kind] || f.kind, link('Open', f.url)])) +
      p('These links open on the GymRamp computer running the factory.', { size: 13, color: KIT.muted })),
    advisories.length ? section('Worth a second look', list(advisories, { html: true, size: 14 })) : '',
    section('Every statement and its source', claimsHtml || p('No statements were recorded.')),
    section('References', refsHtml),
  ],
  closing: ['Thanks for reviewing.'],
});

// Slack gets a short text version; the full review lives in the same form link.
const text = 'Ready for review: ' + title + ' (version ' + course.version + ')\n' +
  (flagged ? 'Flagged by the evidence review: ' + clean(a.rationale) + '\n' : '') +
  (stats.slides || 0) + ' slides, ' + minutes + ' video, ' + (stats.references || 0) + ' sources, ' + (advisories.length) + ' item(s) worth a second look.\n' +
  (media.files || []).map((f) => (LABEL[f.kind] || f.kind) + ': ' + f.url).join('\n') +
  '\nApprove or request changes: %%REVIEW_URL%%';

return [{
  json: {
    subject: (flagged ? 'Review needed (flagged): ' : 'Ready for your review: ') + title,
    html,
    text,
    channel: String(cfg.review_channel || 'gmail').toLowerCase(),
  },
  pairedItem: { item: 0 },
}];

// n8n Code node: "Normalize Decision"   (GymRamp · Course Factory)
// MODE: Run Once for All Items
//
// The Wait node resumes with the submitted form fields at the top level of the item
// (keys are the field LABELS). A send-and-wait node would nest them under `data`, so
// both are read. A wait that times out after 7 days resumes with the item it was
// given -- no Decision field at all -- which is recorded as 'expired', never mistaken
// for an approval. The same holds when the Slack node is disabled (no credential):
// nobody receives a link, so the review expires rather than passing.

const item = $input.first().json || {};
const data = item.data && typeof item.data === 'object' ? item.data : item;
const pick = (name) => {
  const key = Object.keys(data).find((k) => k.toLowerCase().trim() === name);
  return key ? data[key] : undefined;
};

const raw = String(pick('decision') || '').toLowerCase();
const decision = raw.startsWith('approve') ? 'approved' : raw.startsWith('request') || raw.startsWith('reject') ? 'rejected' : 'expired';

return [{
  json: {
    decision,
    approved: decision === 'approved',
    comments: String(pick('comments') || '').trim() || null,
    channel: $('Build Review Message').first().json.channel,
    responded_at: data.submittedAt || data.respondedAt || null,
    status: { approved: 'approved', rejected: 'needs_revision', expired: 'review_expired' }[decision],
  },
  pairedItem: { item: 0 },
}];

// ---- GymRamp email kit ------------------------------------------------------
// Prepended by build-workflows.js to every Code node that writes an email, so all
// messages share one look. Same rules as the earlier newsletter projects, because
// email clients are hostile: inline styles only (Gmail strips <style>), nested
// tables (no flexbox/grid), a centred 640px container on a soft background,
// web-safe fonts, no external images. Everything interpolated is HTML-escaped.

const KIT = {
  font: "system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif",
  navy: '#0B1F33', accent: '#FF6B2C', page: '#F2F4F7', card: '#FFFFFF',
  text: '#1B2733', muted: '#5B6673', rule: '#E4E8EE',
  ok: '#1E7F4F', warn: '#B26A00', bad: '#B3261E',
};

function esc(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
}

function p(text, opts) {
  const o = opts || {};
  return '<p style="margin:0 0 ' + (o.gap == null ? 14 : o.gap) + 'px;font-size:' + (o.size || 15) + 'px;line-height:1.6;color:' +
    (o.color || KIT.text) + ';">' + (o.html ? text : esc(text)) + '</p>';
}

function list(items, opts) {
  const o = opts || {};
  const rows = items.filter(Boolean).map((it) =>
    '<li style="margin:0 0 8px;font-size:' + (o.size || 15) + 'px;line-height:1.55;color:' + KIT.text + ';">' + (o.html ? it : esc(it)) + '</li>').join('');
  return rows ? '<ul style="margin:0 0 14px;padding-left:20px;">' + rows + '</ul>' : '';
}

function section(label, inner) {
  return '<tr><td style="padding:26px 32px 4px;">' +
    '<div style="font-size:12px;letter-spacing:1.4px;font-weight:700;color:' + KIT.navy + ';text-transform:uppercase;">' + esc(label) + '</div>' +
    '<div style="width:40px;height:3px;background:' + KIT.accent + ';margin:8px 0 14px;line-height:3px;font-size:0;">&nbsp;</div>' +
    inner + '</td></tr>';
}

function callout(title, inner, tone) {
  const color = { ok: KIT.ok, warn: KIT.warn, bad: KIT.bad }[tone] || KIT.accent;
  const tint = { ok: '#EEF7F1', warn: '#FFF6E8', bad: '#FCEDEC' }[tone] || '#FFF3EC';
  return '<tr><td style="padding:22px 32px 0;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">' +
    '<tr><td style="background:' + tint + ';border-left:4px solid ' + color + ';padding:14px 18px;">' +
    '<div style="font-size:14px;font-weight:700;color:' + color + ';margin-bottom:6px;">' + esc(title) + '</div>' + inner +
    '</td></tr></table></td></tr>';
}

function button(label, href) {
  return '<table role="presentation" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:6px 0 4px;"><tr>' +
    '<td style="background:' + KIT.accent + ';border-radius:6px;">' +
    '<a href="' + esc(href) + '" style="display:inline-block;padding:13px 26px;font-family:' + KIT.font +
    ';font-size:15px;font-weight:700;color:#FFFFFF;text-decoration:none;">' + esc(label) + '</a></td></tr></table>';
}

// rows: [[label, valueHtml]]
function facts(rows) {
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 10px;">' +
    rows.filter(Boolean).map(([k, v]) =>
      '<tr><td style="padding:7px 12px 7px 0;border-bottom:1px solid ' + KIT.rule + ';font-size:13px;color:' + KIT.muted +
      ';width:38%;vertical-align:top;">' + esc(k) + '</td><td style="padding:7px 0;border-bottom:1px solid ' + KIT.rule +
      ';font-size:14px;color:' + KIT.text + ';vertical-align:top;">' + v + '</td></tr>').join('') + '</table>';
}

function link(label, href) {
  return '<a href="' + esc(href) + '" style="color:' + KIT.accent + ';text-decoration:none;font-weight:600;">' + esc(label) + '</a>';
}

// blocks are <tr> strings from section()/callout(); intro is plain text paragraphs.
function emailLayout(o) {
